// The value of MOUNT_STATE_PARK_ITEM is the parked state of the mount, not the outcome of the
// last request, so a successful unpark has to turn the light off in the same update. Found on a
// NYX-101, where the light stayed on until the next polling cycle corrected it.
static indigo_property_state cached_light_value(const char *property_name, const char *item_name) {
	indigo_item *item = find_cached_item(property_name, item_name);
	return item == NULL ? INDIGO_IDLE_STATE : item->light.value;
}

static void lx200_nyx_park_light_follows_the_mount(void) {
	external_serial_simulator simulator = { 0 };
	bool online = false;
	SERIAL_CHECK_TRUE(start_profile(&simulator, "nyx", NULL));
	online = true;
	SERIAL_CHECK_TRUE(lx_switch(&lx200_mount, MOUNT_PARK_PROPERTY_NAME, MOUNT_PARK_PARKED_ITEM_NAME, true, INDIGO_BUSY_STATE));
	SERIAL_CHECK_TRUE(wait_event(&simulator, "hP", 0));
	SERIAL_CHECK_TRUE(wait_for_property_state(MOUNT_PARK_PROPERTY_NAME, INDIGO_OK_STATE));
	SERIAL_CHECK_EQ_INT(INDIGO_OK_STATE, cached_light_value(MOUNT_STATE_PROPERTY_NAME, MOUNT_STATE_PARK_ITEM_NAME));
	SERIAL_CHECK_TRUE(lx_switch(&lx200_mount, MOUNT_PARK_PROPERTY_NAME, MOUNT_PARK_UNPARKED_ITEM_NAME, true, INDIGO_OK_STATE));
	SERIAL_CHECK_TRUE(wait_event(&simulator, "hR", 0));
	// The polling callback is a second away, so the light can only be off already if the park
	// handler published it.
	SERIAL_CHECK_EQ_INT(INDIGO_IDLE_STATE, cached_light_value(MOUNT_STATE_PROPERTY_NAME, MOUNT_STATE_PARK_ITEM_NAME));
cleanup:
	if (online) { stop_serial_driver(&lx200_mount); }
	stop_external_serial_simulator(&simulator);
}

// A NYX-101 refuses :hQ# while it is parked and answers :hP# with 0 when it cannot park. Both
// replies have to reach the client instead of a park that is published busy and never ends.
static void lx200_nyx_park_commands_report_refusals(void) {
	external_serial_simulator simulator = { 0 };
	bool online = false;
	SERIAL_CHECK_TRUE(start_profile(&simulator, "nyx", NULL));
	online = true;
	SERIAL_CHECK_TRUE(lx_switch(&lx200_mount, MOUNT_PARK_PROPERTY_NAME, MOUNT_PARK_PARKED_ITEM_NAME, true, INDIGO_BUSY_STATE));
	SERIAL_CHECK_TRUE(wait_for_property_state(MOUNT_PARK_PROPERTY_NAME, INDIGO_OK_STATE));
	// Storing the park position is refused while the mount stands parked on it.
	SERIAL_CHECK_TRUE(lx_switch(&lx200_mount, MOUNT_PARK_SET_PROPERTY_NAME, MOUNT_PARK_SET_CURRENT_ITEM_NAME, true, INDIGO_ALERT_STATE));
	SERIAL_CHECK_TRUE(lx_switch(&lx200_mount, MOUNT_PARK_PROPERTY_NAME, MOUNT_PARK_UNPARKED_ITEM_NAME, true, INDIGO_OK_STATE));
	// Unparked it is accepted, and it stores the position the mount parked at. Both requests
	// arrive before the next status poll, so the driver has to know it just unparked the mount
	// rather than wait for the controller to say so.
	SERIAL_CHECK_TRUE(lx_switch(&lx200_mount, MOUNT_PARK_SET_PROPERTY_NAME, MOUNT_PARK_SET_CURRENT_ITEM_NAME, true, INDIGO_OK_STATE));
	SERIAL_CHECK_TRUE(wait_event(&simulator, "hQ", 1));
	// :hF# resets the controller at its home position and leaves it in a cold start standby in
	// which it refuses to park. The refusal has to end the request, not hang it.
	SERIAL_CHECK_TRUE(lx_switch(&lx200_mount, MOUNT_HOME_SET_PROPERTY_NAME, MOUNT_HOME_SET_CURRENT_ITEM_NAME, true, INDIGO_OK_STATE));
	SERIAL_CHECK_TRUE(wait_event(&simulator, "hF", 0));
	SERIAL_CHECK_TRUE(lx_switch(&lx200_mount, MOUNT_PARK_PROPERTY_NAME, MOUNT_PARK_PARKED_ITEM_NAME, true, INDIGO_ALERT_STATE));
	// The refusal leaves the property on the state of the mount, not on the rejected value, so
	// the parked guards of the motion and tracking properties do not lock the client out.
	assert_switch_item_value(MOUNT_PARK_PROPERTY_NAME, MOUNT_PARK_UNPARKED_ITEM_NAME, true);
	// Enabling tracking takes the controller out of standby and the park works again.
	SERIAL_CHECK_TRUE(lx_switch(&lx200_mount, MOUNT_TRACKING_PROPERTY_NAME, MOUNT_TRACKING_ON_ITEM_NAME, true, INDIGO_OK_STATE));
	SERIAL_CHECK_TRUE(lx_switch(&lx200_mount, MOUNT_PARK_PROPERTY_NAME, MOUNT_PARK_PARKED_ITEM_NAME, true, INDIGO_BUSY_STATE));
	SERIAL_CHECK_TRUE(wait_for_property_state(MOUNT_PARK_PROPERTY_NAME, INDIGO_OK_STATE));
cleanup:
	if (online) { stop_serial_driver(&lx200_mount); }
	stop_external_serial_simulator(&simulator);
}

// A NYX-101 answers :GT# with 0 while tracking is disabled and carries the rate it really uses in
// the :GU# status instead. A driver that decodes the 0 reports the lunar rate on every session
// that starts with tracking off.
static void lx200_nyx_tracking_rate_comes_from_status(void) {
	external_serial_simulator simulator = { 0 };
	bool online = false;
	SERIAL_CHECK_TRUE(start_profile(&simulator, "nyx", NULL));
	online = true;
	// The simulator starts not tracking, so :GT# answers 0 during the whole connection.
	assert_switch_item_value(MOUNT_TRACK_RATE_PROPERTY_NAME, MOUNT_TRACK_RATE_SIDEREAL_ITEM_NAME, true);
	assert_switch_item_value(MOUNT_TRACK_RATE_PROPERTY_NAME, MOUNT_TRACK_RATE_LUNAR_ITEM_NAME, false);
	// Every rate the mount reports in its status has to be published back.
	const char *items[] = { MOUNT_TRACK_RATE_SOLAR_ITEM_NAME, MOUNT_TRACK_RATE_LUNAR_ITEM_NAME, MOUNT_TRACK_RATE_KING_ITEM_NAME, MOUNT_TRACK_RATE_SIDEREAL_ITEM_NAME };
	const char *commands[] = { "TS", "TL", "TK", "TQ" };
	for (int i = 0; i < 4; i++) {
		SERIAL_CHECK_TRUE(lx_switch(&lx200_mount, MOUNT_TRACK_RATE_PROPERTY_NAME, items[i], true, INDIGO_OK_STATE));
		SERIAL_CHECK_TRUE(wait_event(&simulator, commands[i], 0));
		// MOUNT_UTC_TIME carries the mount clock, so it is published on every polling cycle and
		// a fresh revision of it means the status has been read again. The coordinates of an
		// idle mount do not change, and an update that says nothing new is suppressed.
		unsigned int revision = property_revision(UTC_TIME_PROPERTY_NAME);
		SERIAL_CHECK_TRUE(wait_for_property_state_seen_after(UTC_TIME_PROPERTY_NAME, INDIGO_OK_STATE, revision));
		assert_switch_item_value(MOUNT_TRACK_RATE_PROPERTY_NAME, items[i], true);
	}
	// A rate the mount changed on its own reaches the client through the status as well.
	SERIAL_CHECK_TRUE(inject_reply(&simulator, "GU", "GnNp(#"));
	for (int i = 0; i < 200 && !find_cached_item(MOUNT_TRACK_RATE_PROPERTY_NAME, MOUNT_TRACK_RATE_LUNAR_ITEM_NAME)->sw.value; i++) {
		indigo_usleep(20000);
	}
	assert_switch_item_value(MOUNT_TRACK_RATE_PROPERTY_NAME, MOUNT_TRACK_RATE_LUNAR_ITEM_NAME, true);
cleanup:
	if (online) { stop_serial_driver(&lx200_mount); }
	stop_external_serial_simulator(&simulator);
}

// A goto does not stop the mount tracking. The NYX-101 status carries "no goto" and "not
// tracking" as independent characters, so a slew with tracking on carries neither and a driver
// that reads them as alternatives publishes tracking off for the whole slew.
static void lx200_nyx_keeps_tracking_while_slewing(void) {
	external_serial_simulator simulator = { 0 };
	bool online = false;
	int off_samples = 0, samples = 0;
	SERIAL_CHECK_TRUE(start_profile(&simulator, "nyx", NULL));
	online = true;
	SERIAL_CHECK_TRUE(lx_switch(&lx200_mount, MOUNT_TRACKING_PROPERTY_NAME, MOUNT_TRACKING_ON_ITEM_NAME, true, INDIGO_OK_STATE));
	// MOUNT_STATE carries the light of the property that changed, in the same update.
	SERIAL_CHECK_EQ_INT(INDIGO_OK_STATE, cached_light_value(MOUNT_STATE_PROPERTY_NAME, MOUNT_STATE_TRACKING_ITEM_NAME));
	SERIAL_CHECK_TRUE(lx_coordinates(18.5, 40.5, INDIGO_BUSY_STATE));
	SERIAL_CHECK_TRUE(wait_event(&simulator, "MS", 0));
	while (find_cached_property(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME)->state == INDIGO_BUSY_STATE && samples < 400) {
		samples++;
		if (!find_cached_item(MOUNT_TRACKING_PROPERTY_NAME, MOUNT_TRACKING_ON_ITEM_NAME)->sw.value) {
			off_samples++;
		}
		indigo_usleep(20000);
	}
	SERIAL_CHECK_TRUE(wait_for_property_state(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, INDIGO_OK_STATE));
	SERIAL_CHECK_TRUE(samples > 0);
	SERIAL_CHECK_EQ_INT(0, off_samples);
	assert_switch_item_value(MOUNT_TRACKING_PROPERTY_NAME, MOUNT_TRACKING_ON_ITEM_NAME, true);
cleanup:
	if (online) { stop_serial_driver(&lx200_mount); }
	stop_external_serial_simulator(&simulator);
}

// A NYX-101 counts a running guide pulse as motion and refuses a goto issued during it. The
// refusal has to reach the client as an alert with the controller's own message, and the next
// goto after the pulse has to work.
static void lx200_nyx_goto_during_a_guide_pulse_is_refused(void) {
	external_serial_simulator simulator = { 0 };
	bool online = false;
	SERIAL_CHECK_TRUE(start_secondary_profile(&simulator, &lx200_guider, "nyx", NULL));
	online = true;
	// Both logical devices share the session: the guider pulses and the mount takes the goto.
	SERIAL_CHECK_TRUE(connect_serial_device(&lx200_mount, simulator.port));
	reset_simulator_context(&lx200_guider);
	enumerate_simulator_device();
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_number_property_1(&simulator_test_client, lx200_guider.device_name, GUIDER_GUIDE_DEC_PROPERTY_NAME, GUIDER_GUIDE_NORTH_ITEM_NAME, 2000));
	SERIAL_CHECK_TRUE(wait_event(&simulator, "Mgn2000", 0));
	// The property cache follows the guider in this fixture, so the state of the master device's
	// coordinates is read through the shared client observation instead.
	SERIAL_CHECK_TRUE(request_mount_coordinates(18.5, 40.5) && wait_for_mount_coordinates_state(INDIGO_ALERT_STATE));
	SERIAL_CHECK_TRUE(wait_for_property_not_busy(GUIDER_GUIDE_DEC_PROPERTY_NAME));
	SERIAL_CHECK_TRUE(request_mount_coordinates(18.5, 40.5) && wait_for_mount_coordinates_state(INDIGO_BUSY_STATE));
	SERIAL_CHECK_TRUE(wait_for_mount_slew_end());
cleanup:
	// The master was connected too, and a device left connected keeps publishing into the shared
	// property cache of the next case.
	if (online) {
		indigo_change_switch_property_1(&simulator_test_client, lx200_mount.device_name, CONNECTION_PROPERTY_NAME, CONNECTION_DISCONNECTED_ITEM_NAME, true);
		stop_serial_driver(&lx200_guider);
	}
	stop_external_serial_simulator(&simulator);
}

static void lx200_transport_loss_and_fresh_session(void) {
	external_serial_simulator simulator = { 0 };
	bool online = false;
	SERIAL_CHECK_TRUE(start_profile(&simulator, "onstep", NULL));
	online = true;
	SERIAL_CHECK_TRUE(lx_coordinates(22, -60, INDIGO_BUSY_STATE));
	SERIAL_CHECK_TRUE(wait_event(&simulator, "MS", 0));
	stop_external_serial_simulator(&simulator);
	bool disconnected = false;
	SERIAL_CHECK_TRUE(lx_switch_after_loss(&lx200_mount, MOUNT_ABORT_MOTION_PROPERTY_NAME, MOUNT_ABORT_MOTION_ITEM_NAME, true, &disconnected));
	printf("    the lost connection was reported by %s\n", disconnected ? "disconnecting the mount" : "ALERT");
	if (!disconnected) {
		disconnect_serial_device(&lx200_mount);
	}
	SERIAL_CHECK_TRUE(start_lx200_simulator(&simulator, "onstep"));
	SERIAL_CHECK_TRUE(connect_serial_device(&lx200_mount, simulator.port));
	SERIAL_CHECK_TRUE(lx_switch(&lx200_mount, MOUNT_ON_COORDINATES_SET_PROPERTY_NAME, MOUNT_ON_COORDINATES_SET_SYNC_ITEM_NAME, true, INDIGO_OK_STATE));
	SERIAL_CHECK_TRUE(lx_coordinates(8, 20, INDIGO_OK_STATE));
cleanup:
	if (online) { stop_serial_driver(&lx200_mount); }
	stop_external_serial_simulator(&simulator);
}

static void lx200_secondary_capability_rejection(void) {
	external_serial_simulator simulator = { 0 };
	bool online = false;
	SERIAL_CHECK_TRUE(start_lx200_simulator(&simulator, "zwo"));
	SERIAL_CHECK_TRUE(bring_up_serial_driver(&lx200_focuser));
	online = true;
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_text_property_1_raw(&simulator_test_client, lx200_mount.device_name, DEVICE_PORT_PROPERTY_NAME, DEVICE_PORT_ITEM_NAME, simulator.port));
	SERIAL_CHECK_TRUE(!connect_serial_device(&lx200_focuser, NULL));
	SERIAL_CHECK_EQ_INT(INDIGO_ALERT_STATE, context.last_connection_state);
	SERIAL_CHECK_TRUE(!connect_serial_device(&lx200_aux, NULL));
	SERIAL_CHECK_EQ_INT(INDIGO_ALERT_STATE, context.last_connection_state);
	SERIAL_CHECK_TRUE(connect_serial_device(&lx200_mount, simulator.port));
cleanup:
	if (online) {
		disconnect_serial_device(&lx200_mount);
		tear_down_serial_driver(&lx200_mount);
	}
	stop_external_serial_simulator(&simulator);
}

static void lx200_driver_metadata_and_base_properties(void) {
	external_serial_simulator simulator = { 0 };
	bool online = false;
	indigo_driver_info info = { 0 };
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_mount_lx200(INDIGO_DRIVER_INFO, &info));
	SERIAL_CHECK_TRUE(!strcmp(info.name, "indigo_mount_lx200"));
	SERIAL_CHECK_TRUE(!strcmp(info.description, "LX200 Mount"));
	SERIAL_CHECK_TRUE(INDIGO_DRIVER_API_GENERATION(info.version) == INDIGO_DRIVER_API_3 && !info.multi_device_support);
	SERIAL_CHECK_EQ_INT(INDIGO_DRIVER_SHUTDOWN, info.status);
	SERIAL_CHECK_TRUE(bring_up_serial_driver(&lx200_mount));
	online = true;
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_mount_lx200(INDIGO_DRIVER_INIT, NULL));
	enumerate_simulator_device();
	const char *base[] = { INFO_PROPERTY_NAME, CONFIG_PROPERTY_NAME, PROFILE_PROPERTY_NAME, PROFILE_NAME_PROPERTY_NAME, CONNECTION_PROPERTY_NAME, DEVICE_PORT_PROPERTY_NAME, DEVICE_BAUDRATE_PROPERTY_NAME, MOUNT_TYPE_PROPERTY_NAME };
	assert_defined_properties(base, ARRAY_SIZE(base));
	SERIAL_CHECK_TRUE(find_cached_property(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME) == NULL);
	SERIAL_CHECK_EQ_INT(16, find_cached_property(MOUNT_TYPE_PROPERTY_NAME)->count);
	for (int i = 0; i < ARRAY_SIZE(profiles); i++) {
		assert_property_has_item(MOUNT_TYPE_PROPERTY_NAME, profiles[i].type);
	}
cleanup:
	if (online) { tear_down_serial_driver(&lx200_mount); }
	stop_external_serial_simulator(&simulator);
}

static void lx200_utc_write_failures_recover(void) {
	external_serial_simulator simulator = { 0 };
	bool online = false;
	SERIAL_CHECK_TRUE(start_profile(&simulator, "meade", NULL));
	online = true;
	const char *items[] = { UTC_TIME_ITEM_NAME, UTC_OFFSET_ITEM_NAME };
	const char *values[] = { "2026-09-15T23:30:45", "-3" };
	const char *commands[] = { "SC09/15/26", "SG+03", "SL20:30:45" };
	for (int i = 0; i < 3; i++) {
		SERIAL_CHECK_TRUE(inject_reply(&simulator, commands[i], "0"));
		unsigned int revision = property_revision(UTC_TIME_PROPERTY_NAME);
		SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_text_property(&simulator_test_client, lx200_mount.device_name, UTC_TIME_PROPERTY_NAME, 2, items, values));
		SERIAL_CHECK_TRUE(wait_for_property_state_seen_after(UTC_TIME_PROPERTY_NAME, INDIGO_ALERT_STATE, revision));
		revision = property_revision(UTC_TIME_PROPERTY_NAME);
		SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_text_property(&simulator_test_client, lx200_mount.device_name, UTC_TIME_PROPERTY_NAME, 2, items, values));
		SERIAL_CHECK_TRUE(wait_for_property_state_seen_after(UTC_TIME_PROPERTY_NAME, INDIGO_OK_STATE, revision));
	}
cleanup:
	if (online) { stop_serial_driver(&lx200_mount); }
	stop_external_serial_simulator(&simulator);
}

static void lx200_manual_reversal_and_axis_stops(void) {
	external_serial_simulator simulator = { 0 };
	bool online = false;
	SERIAL_CHECK_TRUE(start_profile(&simulator, "meade", NULL));
	online = true;
	SERIAL_CHECK_TRUE(wait_complete_polls(&simulator, 1));
	double declination = cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_DEC_ITEM_NAME);
	SERIAL_CHECK_TRUE(lx_switch(&lx200_mount, MOUNT_MOTION_DEC_PROPERTY_NAME, MOUNT_MOTION_NORTH_ITEM_NAME, true, INDIGO_BUSY_STATE));
	SERIAL_CHECK_TRUE(wait_event(&simulator, "Mn", 0));
	// North raises the declination the mount reports, south lowers it again.
	for (int i = 0; i < 50 && cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_DEC_ITEM_NAME) < declination + 0.2; i++) {
		indigo_usleep(100000);
	}
	double raised = cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_DEC_ITEM_NAME);
	SERIAL_CHECK_TRUE(raised >= declination + 0.2);
	SERIAL_CHECK_TRUE(lx_switch(&lx200_mount, MOUNT_MOTION_DEC_PROPERTY_NAME, MOUNT_MOTION_SOUTH_ITEM_NAME, true, INDIGO_BUSY_STATE));
	SERIAL_CHECK_TRUE(wait_event(&simulator, "Qn", 0));
	SERIAL_CHECK_TRUE(wait_event(&simulator, "Ms", 0));
	for (int i = 0; i < 50 && cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_DEC_ITEM_NAME) > raised - 0.2; i++) {
		indigo_usleep(100000);
	}
	SERIAL_CHECK_TRUE(cached_number_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_DEC_ITEM_NAME) <= raised - 0.2);
	SERIAL_CHECK_TRUE(lx_switch(&lx200_mount, MOUNT_MOTION_RA_PROPERTY_NAME, MOUNT_MOTION_EAST_ITEM_NAME, true, INDIGO_BUSY_STATE));
	SERIAL_CHECK_TRUE(wait_event(&simulator, "Me", 0));
	SERIAL_CHECK_TRUE(lx_switch(&lx200_mount, MOUNT_MOTION_RA_PROPERTY_NAME, MOUNT_MOTION_WEST_ITEM_NAME, true, INDIGO_BUSY_STATE));
	SERIAL_CHECK_TRUE(wait_event(&simulator, "Qe", 0));
	SERIAL_CHECK_TRUE(wait_event(&simulator, "Mw", 0));
	SERIAL_CHECK_TRUE(lx_switch(&lx200_mount, MOUNT_MOTION_DEC_PROPERTY_NAME, MOUNT_MOTION_SOUTH_ITEM_NAME, false, INDIGO_OK_STATE));
	SERIAL_CHECK_TRUE(wait_event(&simulator, "Qs", 0));
	SERIAL_CHECK_TRUE(lx_switch(&lx200_mount, MOUNT_MOTION_RA_PROPERTY_NAME, MOUNT_MOTION_WEST_ITEM_NAME, false, INDIGO_OK_STATE));
	SERIAL_CHECK_TRUE(wait_event(&simulator, "Qw", 0));
cleanup:
	if (online) { stop_serial_driver(&lx200_mount); }
	stop_external_serial_simulator(&simulator);
}

static bool secondary_operation(const simulator_driver_case *secondary) {
	if (secondary == &lx200_focuser) {
		return lx_number(secondary, FOCUSER_STEPS_PROPERTY_NAME, FOCUSER_STEPS_ITEM_NAME, 10, INDIGO_OK_STATE);
	}
	return lx_switch(secondary, AUX_POWER_OUTLET_PROPERTY_NAME, "OUTLET_1", true, INDIGO_OK_STATE);
}

static void check_shared_secondary(const simulator_driver_case *secondary) {
	for (int order = 0; order < 2; order++) {
		external_serial_simulator simulator = { 0 };
		bool online = false;
		SERIAL_CHECK_TRUE(start_secondary_profile(&simulator, secondary, "onstep", NULL));
		online = true;
		if (order == 0) {
			disconnect_serial_device(secondary);
		}
		SERIAL_CHECK_TRUE(connect_serial_device(&lx200_mount, simulator.port));
		if (order == 0) {
			SERIAL_CHECK_TRUE(connect_serial_device(secondary, NULL));
		} else {
			reset_simulator_context(secondary);
			enumerate_simulator_device();
		}
		SERIAL_CHECK_TRUE(secondary_operation(secondary));
		disconnect_serial_device(&lx200_mount);
		reset_simulator_context(secondary);
		enumerate_simulator_device();
		SERIAL_CHECK_TRUE(secondary_operation(secondary));
		disconnect_serial_device(secondary);
		SERIAL_CHECK_TRUE(connect_serial_device(&lx200_mount, simulator.port));
		SERIAL_CHECK_TRUE(lx_switch(&lx200_mount, MOUNT_ABORT_MOTION_PROPERTY_NAME, MOUNT_ABORT_MOTION_ITEM_NAME, true, INDIGO_OK_STATE));
cleanup:
		if (online) {
			disconnect_serial_device(secondary);
			disconnect_serial_device(&lx200_mount);
			tear_down_serial_driver(&lx200_mount);
		}
		stop_external_serial_simulator(&simulator);
	}
}

static void lx200_shared_focuser_lifecycle(void) {
	check_shared_secondary(&lx200_focuser);
}

static void lx200_shared_aux_lifecycle(void) {
	check_shared_secondary(&lx200_aux);
}

// A running GOTO owns MOUNT_EQUATORIAL_COORDINATES until it completes: the
// generated change branch refuses an overlapping request instead of retargeting
// the mount mid-slew, and the next request is accepted once the slew is over.
static void lx200_goto_busy_refuses_overlap(void) {
	external_serial_simulator simulator = { 0 };
	bool online = false;
	SERIAL_CHECK_TRUE(start_profile(&simulator, "onstep", NULL));
	online = true;
	SERIAL_CHECK_TRUE(lx_number(&lx200_mount, MOUNT_EPOCH_PROPERTY_NAME, MOUNT_EPOCH_ITEM_NAME, 2000, INDIGO_OK_STATE));
	SERIAL_CHECK_TRUE(lx_coordinates(22, -70, INDIGO_BUSY_STATE));
	SERIAL_CHECK_TRUE(wait_event(&simulator, "MS", 0));
	int before = event_count(&simulator, "MS", NULL);
	const char *coordinate_items[] = { MOUNT_EQUATORIAL_COORDINATES_RA_ITEM_NAME, MOUNT_EQUATORIAL_COORDINATES_DEC_ITEM_NAME };
	double overlapping[] = { 1, 70 };
	SERIAL_CHECK_EQ_INT(INDIGO_OK, indigo_change_number_property(&simulator_test_client, lx200_mount.device_name, MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, 2, coordinate_items, overlapping));
	SERIAL_CHECK_TRUE(wait_for_number_item_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_RA_ITEM_NAME, 22, 0.001));
	SERIAL_CHECK_TRUE(wait_for_number_item_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_DEC_ITEM_NAME, -70, 0.001));
	SERIAL_CHECK_EQ_INT(before, event_count(&simulator, "MS", NULL));
	SERIAL_CHECK_TRUE(wait_for_property_state(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, INDIGO_OK_STATE));
	SERIAL_CHECK_TRUE(lx_coordinates(1, 70, INDIGO_BUSY_STATE));
	SERIAL_CHECK_TRUE(wait_event(&simulator, "MS", before));
	SERIAL_CHECK_TRUE(wait_for_property_state(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, INDIGO_OK_STATE));
	SERIAL_CHECK_TRUE(wait_for_number_item_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_RA_ITEM_NAME, 1, 0.001));
	SERIAL_CHECK_TRUE(wait_for_number_item_value(MOUNT_EQUATORIAL_COORDINATES_PROPERTY_NAME, MOUNT_EQUATORIAL_COORDINATES_DEC_ITEM_NAME, 70, 0.001));
cleanup:
	if (online) { stop_serial_driver(&lx200_mount); }
	stop_external_serial_simulator(&simulator);
}

